commands.command:
install -d -m 0750 /var/log/inventory
cat > /etc/rsyslog.d/20-inventory-receiver.conf <<'ANTRIEB_EOF'
module(load="imtcp")
ruleset(name="inventoryRemote") {
  if ($fromhost-ip == '10.100.198.11' and $programname == 'inventory') then {
    action(type="omfile" file="/var/log/inventory/node2.log" createDirs="on" dirCreateMode="0750" fileCreateMode="0640")
    stop
  }
}
input(type="imtcp" port="514" ruleset="inventoryRemote")
ANTRIEB_EOF
rsyslogd -N1
